 if(role==='topics'){if(!norm(data.keywords))throw Error('At least one keyword is required.');if(data.startYear!==null&&data.startYear!==undefined&&(+data.startYear<1900||+data.startYear>2100))throw Error('Publication year filter must be valid.');if(!Number.isInteger(+data.scopeVersion)||+data.scopeVersion<1)throw Error('Scope version must be a positive integer.');if(original){const keys=['question','keywords','excludeTerms','sourceScope','startYear','rubric'];if(keys.some(k=>norm(original.data[k])!==norm(data[k]))){if(+data.scopeVersion<=+original.data.scopeVersion)throw Error('Changing search scope requires a new scope version; past screening decisions remain unchanged.');if(!fully(['reports','screenings','findings']))throw Error('Cannot re-scope while dependent evidence coverage is incomplete.');if(scoped('screenings',original.id).length||scoped('findings',original.id).length||scoped('reports',original.id).some(r=>r.data.status==='Reviewed'))throw Error('Existing reviewed synthesis is not scope-versioned: preserve the approved topic and create a new scope instead.');}}}
 if(role==='publications'){if(!fully(['publications']))throw Error('Publication register must be complete before DOI/PMID deduplication or identifiers change.');if(!norm(data.doi)&&!norm(data.pmid))throw Error('At least DOI or PMID is required before storing verified metadata. Put uncertain findings in ChatGPT proposals, not as a confirmed publication.');if(data.doi&&!validDOI(data.doi))throw Error('DOI format is not valid.');if(data.pmid&&!/^\d+$/.test(normalizePMID(data.pmid)))throw Error('PMID must be numeric.');data.doi=normalizeDOI(data.doi);data.pmid=normalizePMID(data.pmid);if(all('publications').some(r=>r.id!==id&&((data.doi&&normalizeDOI(r.data.doi)===data.doi)||(data.pmid&&normalizePMID(r.data.pmid)===data.pmid))))throw Error('A saved publication already has this DOI or PMID. Review the existing record; do not create a duplicate.');if(data.url&&!/^https:///i.test(data.url))throw Error('Source URL must be HTTPS.');if(!norm(data.sourceLabel)||!isISO(data.verifiedAt)||!isISO(data.firstSeenAt))throw Error('Publisher metadata needs a source, verification date and first-observed date.');if(original&&['doi','pmid'].some(k=>norm(original.data[k])!==norm(data[k]))&&(!fully(['matches','screenings','findings','reports'])||['matches','screenings','findings'].some(r=>all(r).some(x=>x.data.publicationId===id))||all('reports').some(r=>norm(r.data.references).split(/[\s,;]+/).includes(id))))throw Error('Referenced publication identifiers cannot change without a separate source-correction review.');}
