function editorStart(role,mode,id){if(!canWrite(role))throw Error('No authorized write grant for '+role);let draft={},expectedVersion=null;if(mode!=='create'){const r=find(role,id);if(!r)throw Error('Record unavailable');draft={...r.data};expectedVersion=r.version;if(mode==='duplicate'){draft.name='Copy of '+clip(draft.name,90);expectedVersion=null;if(role==='publications'){draft.doi='';draft.pmid='';draft.verifiedAt='';draft.sourceLabel='';draft.url='';}if(role==='topics'){draft.scopeVersion=1;draft.lastChecked='';}if(role==='matches'){draft.publicationId='';}if(role==='screenings'){draft.publicationId='';draft.stage='New';draft.decision='Uncertain';draft.reviewer='';draft.reviewedAt='';draft.rationale='';}if(role==='findings'){draft.status='Draft';draft.reviewedAt='';draft.reviewer='';}if(role==='reports'){draft.status='Draft';draft.reviewedAt='';draft.author='';}if(role==='runs'){draft.status='partial';draft.startedAt='';draft.completedAt='';draft.source='';draft.savedCount=0;draft.foundCount=0;}}}
