 if(depends.length&&!fully(depends))throw Error('Dependent records are unavailable or incomplete: archive cannot be safely confirmed.');
 if(role==='topics'&&depends.some(other=>all(other).some(x=>x.data.topicId===id)))throw Error('Topic has linked evidence; review and archive dependencies separately.');
 if(role==='publications'&&(depends.filter(x=>x!=='reports').some(other=>all(other).some(x=>x.data.publicationId===id))||all('reports').some(r=>norm(r.data.references).split(/[\s,;]+/).includes(id))))throw Error('Publication has linked screening/evidence records and cannot be archived.');
