kpi"><small>To screen</small><b>'+safeCount(['screenings'],()=>pending.length)+'</b><span>New or being read</span></div><div class="lr-kpi"><small>Missing identifiers</small><b>'+safeCount(['publications'],()=>flag.length)+'</b><span>Unverified candidates only</span></div></div><div class="lr-two"><section class="lr-card">'+section('New additions by month','<span class="lr-small-text">First observed date, not publication date</span>')+(fully(['publications','matches'])?'<div class="lr-bars">'+trend.map(x=>'<div class="lr-bar-col"><strong>'+x.count+'</strong><div class="lr-bar-track"><span style="height:'+Math.max(x.count?8:0,Math.round(100*x.count/max))+'%"></span></div><small>'+esc(x.label)+'</small></div>').join('')+'</div>':'<div class="lr-empty">A complete source window is required for a trend.</div>')+'</section><section class="lr-card">'+section('Review priorities')+'<div class="lr-priority-list">'+(pending.slice(0,5).map(x=>'<div class="lr-priority">'+btn(esc(clip(paperName(x.data.publicationId),56)),'focus:screenings:'+x.id,'lr-inline-link')+'<span>'+esc(x.data.reviewer||'Unassigned')+' · '+date(x.data.due)+'</span></div>').join('')||'<div class="lr-empty">'+(fully(['screenings'])?'No open reading tasks.':'Reading task source is incomplete; backlog is unknown.')+'</div>')+'</div></section></div><section class="lr-card">'+section('Recently matched papers',btn('Browse publications '+icon('arrow'),'nav:feed','lr-btn lr-quiet'))+'<div class="lr-paper-strip">'+(recent.map(m=>'<article><span>'+esc(topicName(m.data.topicId))+'</span>'+btn(esc(paperName(m.data.publicationId)),'focus:publications:'+m.data.publicationId,'lr-paper-link')+'<small>'+esc(date(m.data.discoveredAt))+' · '+esc(m.data.relevance||'Unassessed')+'</small></article>').join('')||'<div class="lr-empty">No publications matched yet.</div>')+'</div></section>';}
function renderTopics(){const items=visibleRows(all('topics'),'topics');const page=pager(items);const current=currentTopic();return h('Research topics','Define questions and version the search scope before collecting papers.',btn(icon('plus')+' New topic','new:topics','lr-btn lr-primary',!canWrite('topics')))+warn(['topics'])+'<section class="lr-topic-grid">'+all('topics').slice(0,4).map(t=>'<article class="lr-topic-card '+(t.id===st.topic?'selected':'')+'"><div class="lr-topic-top">'+statusBadge(t.data.active?'Active':'Paused')+'<span>Scope v'+esc(t.data.scopeVersion||'1')+'</span></div>'+btn(esc(t.data.name),'topic-card:'+t.id,'lr-topic-name')+'<p>'+esc(clip(t.data.question,140))+'</p><div class="lr-chips">'+norm(t.data.keywords).split(',').filter(Boolean).slice(0,3).map(k=>'<span>'+esc(clip(k,24))+'</span>').join('')+'</div><div class="lr-topic-foot"><span>'+esc(t.data.owner||'Unassigned')+'</span>'+btn('Edit','edit:topics:'+t.id,'lr-quiet-mini',!canWrite('topics'))+'</div></article>').join('')+'</section><div class="lr-two lr-topic-layout"><section class="lr-card">'+section('Topic register')+searchBar('topics',['Active','Paused'],'Add topic')+table('topics',page.subset)+page.footer+'</section><section class="lr-card lr-criteria">'+section('Selected search scope',btn('Edit scope','edit:topics:'+st.topic,'lr-btn lr-small',!canWrite('topics')))+(current?'<dl><dt>Research question</dt><dd>'+esc(current.data.question)+'</dd><dt>Keywords</dt><dd>'+esc(current.data.keywords)+'</dd><dt>Exclude terms</dt><dd>'+esc(current.data.excludeTerms||'None')+'</dd><dt>Public sources</dt><dd>'+esc(current.data.sourceScope||'Not specified')+'</dd><dt>Screening rubric</dt><dd>'+esc(current.data.rubric||'Not specified')+'</dd><dt>Scope version</dt><dd>v'+esc(current.data.scopeVersion||'1')+' · previous judgments are not rewritten</dd></dl>':'<div class="lr-empty">Choose a research topic.</div>')+'</section></div>';}
function renderFeed(){const match=scoped('matches'),pubs=all('publications'),linked=match.map(x=>({match:x,paper:pubs.find(p=>p.id===x.data.publicationId)})).filter(x=>x.paper);const q=st.query.toLowerCase(),filtered=linked.filter(x=>(st.filter==='All'||x.match.data.relevance===st.filter)&&(!q||[x.paper.data.name,x.paper.data.authors,x.paper.data.journal,x.paper.data.doi,x.paper.data.pmid].some(v=>String(v||'').toLowerCase().includes(q)))).sort((a,b)=>String(b.paper.data.firstSeenAt||'').localeCompare(String(a.paper.data.firstSeenAt||'')));const p=pager(filtered),newest=filtered[0];return h('Publication feed','Verified metadata and evidence kept separate from screening judgments.',topicChoice())+warn(['publications','matches'])+'<div class="lr-feed-grid"><section class="lr-card">'+section('Saved papers',btn(icon('plus')+' Add publication','new:publications','lr-btn lr-small lr-primary',!canWrite('publications')))+'<div class="lr-toolbar"><label class="lr-search">'+icon('search')+'<input type="search" name="search" data-ui-state="true" data-action="search" aria-label="Search publications" placeholder="Title, author, journal, DOI" value="'+esc(st.query)+'"></label>'+select('Relevance','filter',['All','High','Medium','Low','Unassessed'],st.filter)+'</div><div class="lr-paper-feed">'+(p.subset.map(x=>{const d=x.paper.data,m=x.match.data;return '<article class="lr-paper-item"><div class="lr-paper-top">'+badge(m.relevance||'Unassessed')+'<time>'+esc(date(d.firstSeenAt))+'</time></div>'+btn(esc(clip(d.name,210)),'focus:publications:'+x.paper.id,'lr-feed-title')+'<p>'+esc(clip(d.authors,130))+'</p><div class="lr-paper-meta">'+esc(d.journal||'Journal not recorded')+' · '+date(d.publishedAt)+'</div><div class="lr-paper-bottom"><span>'+esc(d.doi?'DOI '+clip(d.doi,45):d.pmid?'PMID '+d.pmid:'Missing identifier')+'</span>'+btn('View record '+icon('arrow'),'focus:publications:'+x.paper.id,'lr-quiet-mini')+'</div></article>';}).join('')||'<div class="lr-empty">'+(fully(['publications','matches'])?'No saved publications matched this research topic.':'Publication coverage incomplete; matching results not final.')+'</div>')+'</div>'+p.footer+'</section><aside class="lr-feed-side"><div class="lr-card lr-source-card">'+section('Source verification')+'<p>Publisher details are stored as evidence, not AI summaries. Normalize DOI or PMID before saving.</p><div class="lr-verification">'+icon('check')+' DOI and PMID deduplication before create</div><div class="lr-verification">'+icon('check')+' Source and verification date required</div><div class="lr-verification">'+icon('check')+' Screening is a separate reviewed record</div>'+btn('Add topic match','new:matches','lr-btn lr-primary lr-block',!canWrite('matches'))+'</div>'+(newest?'<div class="lr-card lr-small-feature"><small>Most recently observed</small><strong>'+esc(clip(newest.paper.data.name,100))+'</strong><p>'+esc(newest.paper.data.journal)+' · '+date(newest.paper.data.firstSeenAt)+'</p></div>':'')+'</aside></div>';}
function queueColumns(){const stages=['New','Reading','Reviewed','Included','Excluded'];const records=scoped('screenings').filter(x=>!st.query||Object.values(x.data).some(v=>String(v||'').toLowerCase().includes(st.query.toLowerCase())));return '<div class="lr-kanban">'+stages.map(stage=>{const lane=records.filter(x=>x.data.stage===stage),max=Math.max(1,Math.ceil(lane.length/15)),lp=Math.min(max-1,Math.max(0,Number(st.lanePage[stage]||0)));return '<section class="lr-lane"><header><b>'+esc(stage)+'</b><span>'+(fully(['screenings'])?lane.length:'?')+'</span></header><div class="lr-lane-stack">'+(lane.slice(lp*15,(lp+1)*15).map(x=>'<article class="lr-queue-card">'+btn(esc(clip(paperName(x.data.publicationId),90)),'focus:screenings:'+x.id,'lr-queue-title')+'<p>'+esc(x.data.reviewer||'Unassigned')+'</p><div>'+esc(x.data.due?date(x.data.due):'No due date')+' '+statusBadge(x.data.priority||'Medium')+'</div><div class="lr-queue-actions">'+btn('Open review','edit:screenings:'+x.id,'lr-quiet-mini',!canWrite('screenings'))+actions('screenings',x)+'</div></article>').join('')||'<div class="lr-lane-empty">'+(fully(['screenings'])?'No papers':'Coverage incomplete')+'</div>')+'</div><div class="lr-lane-pager">'+btn('Prev','lane-prev:'+stage,'lr-btn lr-small',lp===0)+'<span>'+(lp+1)+' / '+max+'</span>'+btn('Next','lane-next:'+stage,'lr-btn lr-small',lp>=max-1)+'</div></section>';}).join('')+'</div>';}
