function promptText(mode){const topic=currentTopic();const pubs=scoped('matches').map(x=>find('publications',x.data.publicationId)).filter(Boolean).map(p=>p.id+': '+clip(p.data.name,85)+'; DOI='+clip(p.data.doi||'',60)+' PMID='+clip(p.data.pmid||'',15));if(mode==='synthesis')return 'In TrialAgents, read ONLY my authorized saved Included screening decisions and reviewed evidence findings for topic '+(topic?.data.name||'[select topic]')+'. Cut off publications at '+today+'. Check sources and DOI/PMID. Compare methods, findings and limitations; identify inaccessible full text and distinguish metadata from interpretation. Return a cited, explicitly DRAFT synthesis referring to exact TrialAgents publication IDs. Never invent evidence or counts; propose reviewed saves only after my confirmation. Source IDs: '+pubs.slice(0,18).join(' | ');return 'Use TrialAgents current authorized Literature Radar app. Topic: '+(topic?.data.name||'[select topic]')+'. Search question: '+(topic?.data.question||'[edit question]')+'. Keywords: '+(topic?.data.keywords||'')+'. Excluded terms: '+(topic?.data.excludeTerms||'None')+'. Sources: '+(topic?.data.sourceScope||'Public scholarly source pages')+'. From year: '+(topic?.data.startYear||'not limited')+'. Read all existing authorized DOI/PMID identities before search, apply deduplication, and report source/date/coverage. Search only public scholarly metadata, no publisher crawling or copyrighted full text. Propose new publication and topic-match records with DOI/PMID, official verified URL, verification date, first-seen date and rationale for human review. Only after actual approved saves reconcile committed receipts and update run records; Zero new saves permits no_update ONLY after complete and verified scope coverage with approved quiet policy; otherwise partial, and no completion email. If unavailable, report a manual-action checklist. Existing IDs: '+pubs.slice(0,22).join(' | ');}
