function confirmation(){if(!st.confirm)return '';const r=find(st.confirm.role,st.confirm.id);return '<div class="lr-overlay"><div class="lr-confirm" role="alertdialog" aria-modal="true"><h2>Archive record?</h2><p>Archive '+esc(r?.data.name||'this record')+' only after TrialAgents reviewed confirmation. References and audit history remain available under host permissions.</p>'+(st.notice?'<div class="lr-notice" role="status">'+esc(st.notice)+'</div>':'')+'<div>'+btn('Cancel','cancel-delete','lr-btn')+btn('Propose archive','confirm-delete','lr-btn lr-red',!r)+'</div></div></div>';}
const nav=activeTabs.map(t=>{const label=tabs.find(x=>x.id===t)?.label||t;const ico={overview:'grid',topics:'folder',feed:'book',queue:'rows',synthesis:'file',monitor:'radar'};return btn(icon(ico[t])+'<span class="lr-nav-full">'+esc(label)+'</span><span class="lr-nav-short">'+esc(({overview:'Overview',topics:'Topics',feed:'Papers',queue:'Queue',synthesis:'Synthesis',monitor:'Monitoring'})[t]||label)+'</span>','nav:'+t,'lr-nav '+(st.tab===t?'active':''));}).join('');
const shell='<div class="lr-layout"><aside class="lr-side"><div class="lr-app-label"><strong>'+esc(st.layout.heading)+'</strong></div><nav aria-label="Literature Radar pages" class="lr-nav-list">'+nav+'</nav></aside>';
const content=st.tab==='overview'?renderOverview():st.tab==='topics'?renderTopics():st.tab==='feed'?renderFeed():st.tab==='queue'?renderQueue():st.tab==='synthesis'?renderSynthesis():renderMonitor();
const html=shell+'<main class="lr-main">'+(cfg.demoLabel?'<div class="lr-demo-ribbon">FICTIONAL RECORDS · LOCAL PREVIEW ONLY · NO DATA SAVED TO TRIALAGENTS</div>':'')+(st.notice&&!st.editor&&!st.confirm?'<div class="lr-notice" role="status">'+esc(st.notice)+btn(icon('close'),'dismiss-notice','lr-notice-close',false,'aria-label="Dismiss notice"')+'</div>':'')+content+'</main></div>'+selectedPanel()+editorPanel()+confirmation();
return {html,css:RADAR_CSS,state:st};
